#!/usr/bin/env python3
"""Check synthetic PDFs generated by PdfReportInstrumentation (requires Poppler tools)."""
from pathlib import Path
import re
import subprocess
import sys

root = Path(sys.argv[1]) if len(sys.argv) == 2 else Path('/tmp/open-pressure-pdf-output')
for language in ('en', 'de', 'ar'):
    path = root / f'report-{language}.pdf'
    meta = subprocess.check_output(['pdfinfo', str(path)], text=True)
    count = int(re.search(r'^Pages:\s+(\d+)', meta, re.M)[1])
    details = subprocess.check_output(['pdfinfo', '-f', '1', '-l', str(count), str(path)], text=True)
    sizes = re.findall(r'Page\s+\d+ size:\s+([\d.]+) x ([\d.]+)', details)
    assert len(sizes) == count and count >= 8, (language, 'pagination')
    assert all(
        (float(w) < float(h)) if i == 0 else (float(w) > float(h))
        for i, (w, h) in enumerate(sizes)
    ), (language, 'orientation')
    text = subprocess.check_output(['pdftotext', '-layout', str(path), '-'], text=True)
    for number in range(1, 122):
        assert f'RecordMarker{number:03d}' in text, (language, number)
    assert 'LongNoteStart' in text and 'LongNoteEnd' in text, (language, 'note ends')
    # Crop the notes column; repeated table headings may interrupt a phrase across pages.
    notes = subprocess.check_output(
        ['pdftotext', '-f', '6', '-x', '610', '-y', '100', '-W', '196', '-H', '449', str(path), '-'],
        text=True,
    )
    for token in ('Full', 'note', 'text.'):
        assert notes.count(token) == 900, (language, token, notes.count(token))
    assert 'kPa' in text, (language, 'original pressure unit')
    if language == 'en':
        assert '8:00:37' in text, 'Detailed record time must preserve seconds'
        assert '(received)' in text, 'Missing measurement time must be marked'
    print(f'{language}: {count} pages; orientation, all 121 records, full long note and original units passed')
